# ছবির ফাইলের নাম = <shop>-<NN>.jpg (পণ্য), <shop>-banner-<N>.jpg (ব্যানার)
import json, pathlib

PHOTO = ("professional e-commerce product photo, {s}, centered, soft natural studio lighting, "
         "realistic textures, sharp focus, square 1:1, no text, no logo, no watermark, no people")
BANNER = ("wide website hero banner photo, {s}, soft natural light, realistic, lots of empty space on the left "
          "for text, 16:6 aspect ratio, no text, no logo, no watermark")

def P(cat, name, price, compare, prompt, bg, variants=None):
    return dict(cat=cat, name=name, price=price, compare=compare,
                prompt=PHOTO.format(s=f"{prompt}, on {bg}"), variants=variants or [])

